// ========================================================================
// HMAC-Vorbereitung — extrahiert rawBody und expectedSignature.
// Der HMAC selbst wird im nachfolgenden Crypto-Node berechnet (kein
// require('crypto') noetig — das ist seit n8n 1.71 in der JS-Sandbox
// gesperrt: "Module 'crypto' is disallowed").
// ========================================================================

const item = $input.first();
const json = item.json;

// rawBody robust extrahieren — Webhook ist mit rawBody:true konfiguriert,
// also liegt der Body als binary an. Die Signatur muss byte-identisch zum
// Backend-Body sein (sonst HMAC-Mismatch).
let rawBodyString;
if (item.binary?.data?.data) {
  rawBodyString = Buffer.from(item.binary.data.data, 'base64').toString('utf-8');
} else if (typeof item.binary?.data === 'string') {
  rawBodyString = Buffer.from(item.binary.data, 'base64').toString('utf-8');
} else {
  // Fallback: re-stringify (nur fuer Edge-Cases ohne rawBody)
  rawBodyString = JSON.stringify(json.body ?? json);
}

const signatureHeader = json.headers?.['x-signature'] || '';
const expectedSignature = signatureHeader.startsWith('sha256=')
  ? signatureHeader.slice('sha256='.length)
  : '';

// Hartkodiertes Shared-Secret (= Secret im App-Notification-Ziel).
// NICHT $env nutzen: n8n mit Task-Runner blockt das ("access to env vars denied").
const secret = 'eca347f5952de611a6b17fb099b80b6b230ad110eae36515c3267d3f43ad17f3';
const skipSignatureCheck = !secret;

// Wenn das Secret konfiguriert ist, MUSS ein Header da sein.
if (!skipSignatureCheck && !expectedSignature) {
  throw new Error('Fehlende oder ungueltige X-Signature');
}

return [{
  json: {
    ...json,
    rawBodyString,
    expectedSignature,
    skipSignatureCheck,
  },
}];

// ========================================================================
// Signatur-Vergleich nach dem Crypto-Node.
// Konstantzeit-aehnlicher Vergleich in pure JS — kein require('crypto') noetig.
// ========================================================================

const json = $input.first().json;
const expectedSignature = String(json.expectedSignature ?? '');
const computedHmac = String(json.computedHmac ?? '');
const skipSignatureCheck = json.skipSignatureCheck === true;

if (skipSignatureCheck) {
  return [{ json: { ...json, _signatureValid: true, _signatureSkipped: true } }];
}

if (expectedSignature.length !== computedHmac.length || expectedSignature.length === 0) {
  throw new Error('Ungueltige HMAC-Signatur');
}

let diff = 0;
for (let i = 0; i < expectedSignature.length; i++) {
  diff |= expectedSignature.charCodeAt(i) ^ computedHmac.charCodeAt(i);
}
if (diff !== 0) {
  throw new Error('Ungueltige HMAC-Signatur');
}

return [{ json: { ...json, _signatureValid: true } }];

// ========================================================================
// HTML-Mail: Hauptdeputat geaendert (gehaltsrelevant)
// CREDO Corporate Design der Verwaltung -- Outlook-optimiert
// Klar, einfach, zeigt pro Lehrer/Monat: alt -> neu (Differenz)
// ========================================================================

const data = $input.first().json;
const payload = data.body?.payload || data.payload || data;
const aenderungen = payload.aenderungen || [];
const count = payload.count || aenderungen.length;
const timestamp = data.body?.timestamp || data.timestamp;
const tsFormatted = timestamp
  ? new Date(timestamp).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' })
  : new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const monatsnamen = [
  '', 'Januar', 'Februar', 'M\u00e4rz', 'April', 'Mai', 'Juni',
  'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'
];

// App-URL (CREDO Stellenist-Berechnung -- Verwaltung)
const APP_URL = 'https://deputat.fes-credo.de';
const LINK_HISTORIE = APP_URL + '/historie';
const LINK_DEPUTATE = APP_URL + '/deputate';

// Robuste alt/neu-Extraktion: deckt beide Backend-Pfade ab
// - sync v1: { alt: number, neu: number }
// - sync v2: { perioden: [{ alt: { gesamt }, neu: { gesamt } }] }
function extractAltNeu(a) {
  if (typeof a.alt === 'number' && typeof a.neu === 'number') {
    return { alt: a.alt, neu: a.neu };
  }
  if (Array.isArray(a.perioden) && a.perioden.length > 0) {
    const first = a.perioden[0];
    const last = a.perioden[a.perioden.length - 1];
    const altG = Number(first?.alt?.gesamt ?? 0);
    const neuG = Number(last?.neu?.gesamt ?? 0);
    return { alt: altG, neu: neuG };
  }
  return { alt: 0, neu: 0 };
}

// Einheitliches Sortieren: nach Lehrername, dann Jahr/Monat
const sortedAenderungen = [...aenderungen].sort((x, y) => {
  const n = (x.vollname || '').localeCompare(y.vollname || '', 'de');
  if (n !== 0) return n;
  return (x.jahr - y.jahr) || (x.monat - y.monat);
});

const rows = sortedAenderungen.map(a => {
  const { alt, neu } = extractAltNeu(a);
  const diff = neu - alt;
  const diffStr = (diff > 0 ? '+' : '') + diff.toFixed(1);
  const diffColor = diff > 0 ? '#6BAA24' : '#E2001A';
  const monat = monatsnamen[a.monat] || a.monat;
  return `
    <tr>
      <td style="padding:10px 14px;border-bottom:1px solid #E5E5E5;font-family:Montserrat,Arial,sans-serif;font-size:14px;color:#333333;">
        ${a.vollname || '\u2013'}
      </td>
      <td style="padding:10px 14px;border-bottom:1px solid #E5E5E5;font-family:Montserrat,Arial,sans-serif;font-size:13px;color:#777777;text-align:center;">
        ${monat} ${a.jahr}
      </td>
      <td style="padding:10px 14px;border-bottom:1px solid #E5E5E5;font-family:Montserrat,Arial,sans-serif;font-size:14px;text-align:center;color:#575756;">
        ${alt.toFixed(1)}
      </td>
      <td style="padding:10px 14px;border-bottom:1px solid #E5E5E5;font-family:Montserrat,Arial,sans-serif;font-size:14px;text-align:center;font-weight:700;color:#575756;">
        ${neu.toFixed(1)}
      </td>
      <td style="padding:10px 14px;border-bottom:1px solid #E5E5E5;font-family:Montserrat,Arial,sans-serif;font-size:14px;text-align:center;font-weight:700;color:${diffColor};">
        ${diffStr}
      </td>
    </tr>`;
}).join('');

const html = `<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" lang="de">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta http-equiv="X-UA-Compatible" content="IE=edge">
  <title>Deputat-&Auml;nderung -- CREDO Stellenist</title>
  <!--[if mso]>
  <noscript>
    <xml>
      <o:OfficeDocumentSettings>
        <o:PixelsPerInch>96</o:PixelsPerInch>
      </o:OfficeDocumentSettings>
    </xml>
  </noscript>
  <![endif]-->
</head>
<body style="margin:0;padding:0;background-color:#F4F4F4;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;">
  <!--[if mso]><table role="presentation" width="600" align="center" cellpadding="0" cellspacing="0" border="0"><tr><td><![endif]-->
  <table role="presentation" align="center" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:640px;margin:20px auto;background-color:#FFFFFF;border-collapse:collapse;">
    <!-- Header (CREDO Dunkelgrau #575756) -->
    <tr>
      <td style="background-color:#575756;padding:24px 30px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
          <tr>
            <td style="font-family:Montserrat,Arial,sans-serif;font-size:20px;font-weight:700;color:#FFFFFF;letter-spacing:0.5px;">
              CREDO Stellenist
            </td>
            <td style="font-family:Montserrat,Arial,sans-serif;font-size:12px;color:#BBBBBB;text-align:right;vertical-align:bottom;">
              Automatische Benachrichtigung
            </td>
          </tr>
        </table>
      </td>
    </tr>
    <!-- Alert Bar (CREDO Rot #E2001A -- gehaltsrelevant) -->
    <tr>
      <td style="background-color:#E2001A;padding:12px 30px;font-family:Montserrat,Arial,sans-serif;font-size:13px;font-weight:600;color:#FFFFFF;letter-spacing:0.3px;">
        ${count} gehaltsrelevante Deputat-&Auml;nderung${count === 1 ? '' : 'en'}
      </td>
    </tr>
    <!-- Content -->
    <tr>
      <td style="padding:24px 30px 8px;">
        <p style="font-family:Montserrat,Arial,sans-serif;font-size:14px;color:#575756;margin:0 0 8px;line-height:1.5;">
          Beim letzten Untis-Sync wurde${count === 1 ? '' : 'n'} <strong>${count}</strong> &Auml;nderung${count === 1 ? '' : 'en'} am Hauptdeputat erkannt.
        </p>
        <p style="font-family:Montserrat,Arial,sans-serif;font-size:13px;color:#E2001A;margin:0 0 18px;line-height:1.5;font-weight:600;">
          Diese &Auml;nderungen sind gehaltsrelevant und erfordern ggf. eine Anpassung der Verg&uuml;tung.
        </p>
        <!-- Tabelle -->
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;border:1px solid #E5E5E5;">
          <tr style="background-color:#F7F7F7;">
            <th style="padding:10px 14px;font-family:Montserrat,Arial,sans-serif;font-size:12px;font-weight:600;color:#575756;text-align:left;text-transform:uppercase;letter-spacing:0.5px;border-bottom:2px solid #E0E0E0;">
              Lehrkraft
            </th>
            <th style="padding:10px 14px;font-family:Montserrat,Arial,sans-serif;font-size:12px;font-weight:600;color:#575756;text-align:center;text-transform:uppercase;letter-spacing:0.5px;border-bottom:2px solid #E0E0E0;">
              Monat
            </th>
            <th style="padding:10px 14px;font-family:Montserrat,Arial,sans-serif;font-size:12px;font-weight:600;color:#575756;text-align:center;text-transform:uppercase;letter-spacing:0.5px;border-bottom:2px solid #E0E0E0;">
              Alt
            </th>
            <th style="padding:10px 14px;font-family:Montserrat,Arial,sans-serif;font-size:12px;font-weight:600;color:#575756;text-align:center;text-transform:uppercase;letter-spacing:0.5px;border-bottom:2px solid #E0E0E0;">
              Neu
            </th>
            <th style="padding:10px 14px;font-family:Montserrat,Arial,sans-serif;font-size:12px;font-weight:600;color:#575756;text-align:center;text-transform:uppercase;letter-spacing:0.5px;border-bottom:2px solid #E0E0E0;">
              Diff
            </th>
          </tr>
          ${rows}
        </table>
        <p style="font-family:Montserrat,Arial,sans-serif;font-size:12px;color:#999999;margin:14px 0 0;line-height:1.5;">
          Die jeweilige Schule sehen Sie direkt in der Anwendung im Lehrer-Profil.
        </p>
      </td>
    </tr>
    <!-- Action Button -->
    <tr>
      <td style="padding:18px 30px 8px;text-align:center;">
        <!--[if mso]><v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" href="${LINK_HISTORIE}" style="height:42px;v-text-anchor:middle;width:280px;" arcsize="10%" strokecolor="#575756" fillcolor="#575756"><center style="color:#ffffff;font-family:Montserrat,Arial,sans-serif;font-size:14px;font-weight:bold;">In CREDO Stellenist &ouml;ffnen</center></v:roundrect><![endif]-->
        <!--[if !mso]><!-->
        <a href="${LINK_HISTORIE}" target="_blank" style="display:inline-block;padding:11px 28px;background-color:#575756;color:#FFFFFF;font-family:Montserrat,Arial,sans-serif;font-size:14px;font-weight:600;text-decoration:none;border-radius:6px;line-height:20px;">
          In CREDO Stellenist &ouml;ffnen
        </a>
        <!--<![endif]-->
      </td>
    </tr>
    <!-- Sekundaer-Link -->
    <tr>
      <td style="padding:0 30px 22px;text-align:center;">
        <a href="${LINK_DEPUTATE}" target="_blank" style="font-family:Montserrat,Arial,sans-serif;font-size:12px;color:#575756;text-decoration:underline;">
          Direkt zur Deputat-&Uuml;bersicht
        </a>
      </td>
    </tr>
    <!-- Footer -->
    <tr>
      <td style="background-color:#F7F7F7;padding:16px 30px;border-top:1px solid #E5E5E5;">
        <p style="font-family:Montserrat,Arial,sans-serif;font-size:11px;color:#999999;margin:0;line-height:1.5;">
          Gesendet am ${tsFormatted} &middot; CREDO Schulen &middot; Stellenist-Berechnung<br>
          Diese E-Mail wurde automatisch generiert. Bitte nicht antworten.
        </p>
      </td>
    </tr>
  </table>
  <!--[if mso]></td></tr></table><![endif]-->
</body>
</html>`;

return [{
  json: {
    html,
    subject: `CREDO Stellenist: ${count} Deputat-\u00c4nderung${count === 1 ? '' : 'en'} (gehaltsrelevant)`,
    count
  }
}];
